 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    # Discover period from diagonal color bands (constant column-row).
    # Choose smallest period for which every occupied residue has a unique color.
    diag={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                d=c-r
                if d in diag and diag[d]!=v: return [row[:] for row in grid]
                diag[d]=v
    for p in range(1, max(h,w)*2+1):
        residues={}
        ok=True
        for d,v in diag.items():
            k=d%p
            if k in residues and residues[k]!=v:
                ok=False;break
            residues[k]=v
        if ok and len(residues)>=4:
            # Only extrapolate when period has consistent clue assignments.
            out=[[0]*w for _ in range(h)]
            for r in range(h):
                for c in range(w): out[r][c]=residues.get((c-r)%p,0)
            return out
    return [row[:] for row in grid]

if __name__=='__main__':
    pass
